) AS (
  VALUES 
    (693::BIGINT, 'No enseña absolutamente nada ni explica nada, solo lee presentaciones y las clases las hace cortas por eso mismo. Luego en los exámenes pregunta cosas que claramente ni el explicó.'::TEXT, 4.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('65','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2026-09-04T00:00:00+00:00'::TIMESTAMPTZ, '9a49ae6b77c5bce696751415aff9d93aff4f7ac341cebba008e8f51d91e61e06'::TEXT, ARRAY[2961]::BIGINT[]),
    (693::BIGINT, 'Explica claro y directo al punto, clases cortas y el profe es demasiado buena gente, es fácil pasar pero sí se tiene que ser autodidacta'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2026-06-24T00:00:00+00:00'::TIMESTAMPTZ, '41c4024353e2c39367b9f9887c68d67fc23ce8b10e2d40c11bfe65b025129d63'::TEXT, ARRAY[2511]::BIGINT[]),
    (693::BIGINT, 'Con Leonardo se pasa muy bien la clase; se aprende bastante y suelen durar poco las clases. Para los exámenes sirve mucho repasar sus videos del canal de las clases virtuales que tuvo'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'La participación importa', 'Tomaría su clase nuevamente']::TEXT[], '2026-06-24T00:00:00+00:00'::TIMESTAMPTZ, '7916ea37f60b30fc76707bd1dc40cc99d0cc3ae0e39bc54693b69d3cbead1339'::TEXT, ARRAY[1055]::BIGINT[]),
    (693::BIGINT, 'Se tiene que ser muy autodidacta para aprobar el curso'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Deja trabajos largos']::TEXT[], '2026-06-03T00:00:00+00:00'::TIMESTAMPTZ, '41b846ff7e041390cfa298e727292d75fa6b12880ec4b6ae750b61d11270759c'::TEXT, ARRAY[2511]::BIGINT[]),
    (693::BIGINT, 'El profe es buena nota y explica la materia de forma clara y rápida. El problema es que no profundiza, por lo que no se aprende mucho. La mayoría de clases virtuales solo fueron ver grabaciones de clases del 2020/21. Si de verdad le interesa la materia y aprender, le recomiendo buscar otra opción.'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Pocos exámenes']::TEXT[], '2026-01-03T00:00:00+00:00'::TIMESTAMPTZ, '9fab22de31c92d7cc11e349ea87d947acc84494c7c04a9023f4e41338e88ed4b'::TEXT, ARRAY[2962]::BIGINT[]),
    (693::BIGINT, 'Si quiere entender, o si quiere aprender realmente algo. No meta con este mae'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2025-12-09T00:00:00+00:00'::TIMESTAMPTZ, '94a2df54c2b5c2be4f75225b6979a1e9974b54d53a9463460cb439e0f2546f4e'::TEXT, ARRAY[2962]::BIGINT[]),
    (693::BIGINT, 'Creí que datos 1 sería un curso interesante, aunque honestamente no aprendí casi nada. Nos atrasamos un montón con la materia y dejó muchísimas clases asincrónicas de verse un video.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-11-29T00:00:00+00:00'::TIMESTAMPTZ, '564b394b9fcf4fb007f2267381c5f99db1bd74014e2364a833c0866247332b07'::TEXT, ARRAY[2962]::BIGINT[]),
    (693::BIGINT, 'Clases cortas y explica las ideas generales de los temas, pero si deja claras las cosas. Es bastante comprensivo en pedir más tiempo para las entregas y en general hizo sencillo el curso, aunque siento que no se aprende mucho.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo']::TEXT[], '2025-07-22T00:00:00+00:00'::TIMESTAMPTZ, '008cdc71849ed977b9c9b17aa5859fd1dc10dc20caaa9029d86ec76e5ac879b6'::TEXT, ARRAY[2983]::BIGINT[]),
    (693::BIGINT, 'Muy bueno como profe y persona, siempre dispuesto a ayudar y resolver dudas. Las clases son cortas y entretenidas, aunque a veces puede ser un poco vago para explicar los temas.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Pocos exámenes', 'Tomaría su clase nuevamente']::TEXT[], '2025-07-21T00:00:00+00:00'::TIMESTAMPTZ, '2f56d1ea2f46c1dbf7d27517d023969c0815beeb162ae0f98b2c170a775d91ef'::TEXT, ARRAY[2983]::BIGINT[]),
    (693::BIGINT, 'Pasar el curso con él es relativamente fácil, pero no es la mejor opción para aprender. Muchas clases solo eran videos (a veces olvidaba enviarlos), aunque el profe es muy bueno, explica los temas muy bien y las evaluaciones son justas.'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-07-07T00:00:00+00:00'::TIMESTAMPTZ, 'a9d47e7035faa45045024d57408c403f99ced9354a3a938b89dbe1488adc7c33'::TEXT, ARRAY[2965]::BIGINT[]),
    (693::BIGINT, 'La verdad, el profesor deja mucho que desear. Casi siempre llega tarde y solo se basa en presentaciones para dar la clase. No explica a fondo ni da ejemplos claros, y si uno no tiene bases sólidas en programación, es muy fácil quedarse atrás'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Exámenes retadores']::TEXT[], '2025-06-08T00:00:00+00:00'::TIMESTAMPTZ, '9fb8989cd220e07416d476bce0be6dd295861f3bad360ffb0c356fdb6bcfb6a4'::TEXT, ARRAY[2511]::BIGINT[]),
    (693::BIGINT, 'Es un profesor regular, explica con presentaciones y atiende dudas al momento de la clase. Es un poco flojo como profesor, califica relativamente bien. La materia en sí es abstracta, y si no se le pregunta concretamente no da apoyo aparte de las presentaciones. Ni bueno ni malo'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('65','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico']::TEXT[], '2025-05-22T00:00:00+00:00'::TIMESTAMPTZ, '57c4bf83bf7b650bfa6eac22e592d9ccbd3ef73773a6cd09bcb16e1f50732241'::TEXT, ARRAY[2511]::BIGINT[]),
    (693::BIGINT, 'Es un profesor bastante bueno, es divertido tener clases con el y en general se pasa bien en sus clases. De mi parte califica un poco duro y no ayuda mucho al estudiante... Pero definitivamente es muy profesor y se puede matricular con él, hágalo.'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('55','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Respetado por los estudiantes', 'Brinda apoyo']::TEXT[], '2025-05-22T00:00:00+00:00'::TIMESTAMPTZ, '1ff88db33436f12677a84333d9e8d7b15810e975d31565d0e4aa94650a189956'::TEXT, ARRAY[2511]::BIGINT[]),
    (693::BIGINT, 'Muy vacilón, las clases no duran mucho pero es porque explica los conceptos muy rápido y muy bien, eso sí, para aprender bien todo hay que investigar por cuenta propia y ponerse pilas a hacer practicas porque las explicaciones de clase son bastante rápidas, 10/10 super recomendado.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Inspirador', 'Tomaría su clase nuevamente']::TEXT[], '2025-05-22T00:00:00+00:00'::TIMESTAMPTZ, 'd8d1f5d544c624e94404d480fac073c55a046583e80b4bfafde92359e4d4a6d8'::TEXT, ARRAY[2511]::BIGINT[]),
    (693::BIGINT, 'Buen profe, las explicaciones son claras y las clases no son aburridas. Los exámenes suelen ser muy duros pero si se esfuerza con proyectos y tareas sí pasa.'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('60','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2025-02-09T00:00:00+00:00'::TIMESTAMPTZ, '4e26287754b275988ab8f9a5002e8769f44c6a3388ca47971893724a13cfdbb3'::TEXT, ARRAY[2983]::BIGINT[]),
    (693::BIGINT, 'El profesor da explicaciones muy claras y hace evaluaciones bastante sencillas'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2024-12-16T00:00:00+00:00'::TIMESTAMPTZ, '3f55c4476d23ce72336e6b9e41687ca9155ec32241073c68dabd9e4bb32abbf0'::TEXT, ARRAY[2962, 2965]::BIGINT[]),
    (693::BIGINT, 'No es el mejor profe pero se pasa facil con él. Los quices son sencillos y muchas veces son en pareja, en cuanto a los proyectos revisa mas que todo la funcionalidad y muy pocas veces pide ver el codigo La parte mala es que en el curso no se ve codigo en sí entonces hay que buscar por cuenta propia'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico']::TEXT[], '2024-11-26T00:00:00+00:00'::TIMESTAMPTZ, '144088e7a89749338628ff601639fe15e9022a88431c2b39ff696c02f9902b23'::TEXT, ARRAY[2962, 2965]::BIGINT[]),
    (693::BIGINT, 'Mae hagase el favor y matricule con este profe, las clases son excelentes y claras. El profesor es muy flexible en cuanto a las clases y es muy buena nota.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Respetado por los estudiantes']::TEXT[], '2024-06-24T00:00:00+00:00'::TIMESTAMPTZ, '2bd2b31424636932408a54c11c791961a3e3848e8a55421567f4e74f6e606722'::TEXT, ARRAY[2511]::BIGINT[]),
    (693::BIGINT, 'Clases son concisas y claras, no deja muchos trabajos , es flexible.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2024-06-20T00:00:00+00:00'::TIMESTAMPTZ, '49daab5eebc071aacb660dcc814540a3b71e462ee797f81a963f7d50ccff349f'::TEXT, ARRAY[2511]::BIGINT[]),
    (693::BIGINT, 'De los mejores profes del TEC, y me atrevo a decir el mejor profe para Datos 1. Conoce muy bien la materia y sabe explicarla, y siempre dispuesto para resolver dudas . Califica justo, pero a la vez toma en cuenta situaciones como abandono de compañeros de grupo y dificultad del proyecto'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2023-12-04T00:00:00+00:00'::TIMESTAMPTZ, 'a212f1c972cc76be9a2146497bdf5bebf0497dcf6a5c8407a2c1e5c63e795e34'::TEXT, ARRAY[2962, 2965]::BIGINT[]),
    (693::BIGINT, 'Sus explicaciones son bastante claras, hace varios quices (los cuales no son dificiles) por lo que hay que llevar la materia al día, también ayuda mucho con las calificaciones con tal de que uno pueda pasar el curso'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Clase fácil', 'Muy cómico', 'Da buena retroalimentación']::TEXT[], '2023-12-01T00:00:00+00:00'::TIMESTAMPTZ, '3478ec9d1123f310f225fd3365e2c4010a60bbc56f758593d72f721de36031ee'::TEXT, ARRAY[2962, 2965]::BIGINT[]),
    (693::BIGINT, 'Es un profesor excelente, califica bastante suave y siempre esta dispuesto a ayudar a los estudiantes. El sabe mucho del tema y explica bastante bien. Matricularía con el sin duda.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2023-11-21T00:00:00+00:00'::TIMESTAMPTZ, 'fe6ffad7bdfef9e605c616970f8231dd079fb0a2b60345dd9c53575cb6413712'::TEXT, ARRAY[2962]::BIGINT[]),
    (693::BIGINT, 'Es un profe que sabe del tema y se sabe explicar muy bien, califica de manera suave siempre ayudando a los estudiantes. También está dispuesto a responder las dudas que uno tenga, si tienen la posibilidad de matricular con él, haganlo'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2023-11-20T00:00:00+00:00'::TIMESTAMPTZ, 'b23a975235705fdde52f3f0fc7cfcfca42dc68aa17fd827ac0e7e3ffa23bd8eb'::TEXT, ARRAY[2962]::BIGINT[]),
    (693::BIGINT, 'Uno de los mejores profesor del TEC, sus clases son cortas y concisas, contesta rápido las dudas, y trata de que todo quede lo más claro posible, requiere de ser en gran parte autodidacta, pero en si toda la carrera trata sobre eso, entonces debería de acostumbrarse. Matricularía con el sin duda'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2023-11-20T00:00:00+00:00'::TIMESTAMPTZ, '8cb8b50b90f074e74561b48ddfaee8f06606a3421592267dcc60bf6960cde713'::TEXT, ARRAY[2962, 2965]::BIGINT[]),
    (693::BIGINT, 'No es un profe que se involucra en los procesos de la carrera, hablando de la parte administrativa. No obstante, sus clases son bastante agradables, se aprende lo necesario y justo para los exámenes.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Tomaría su clase nuevamente']::TEXT[], '2023-06-21T00:00:00+00:00'::TIMESTAMPTZ, '496651f0c780584154912a09e8b5d3e0c1de7b6f5019a1934cc5357db628867e'::TEXT, ARRAY[2965]::BIGINT[]),
    (693::BIGINT, 'Sus clases son cortas porque va directo a lo importante siempre está dispuesto a ayudar a los estudiantes, los proyectos los califica relativamente suave buscando no perjudicar mucho al estudiante, es buen profesor, contesta muy rápido las dudas'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2023-06-20T00:00:00+00:00'::TIMESTAMPTZ, '0f50e631bcb6ac4fd1eebc5ffcd03878f095b4cf049c21dfb88822d50a0b287d'::TEXT, ARRAY[2965]::BIGINT[]),
    (693::BIGINT, 'Hace clases muy cortas y al grano. En mi opinión califica bastante suave los proyectos. Explica bien, y lo suficiente para que le vaya bien en los exámenes y quices. Contesta muy rápido las dudas'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo']::TEXT[], '2023-06-19T00:00:00+00:00'::TIMESTAMPTZ, '684f8abd141bf78426eac70acf573a596159167477e8bd287ac5626a976a4a44'::TEXT, ARRAY[2965]::BIGINT[]),
    (693::BIGINT, 'Posiblemente una de los mejores profesores de esta Universidad, es sumamente claro y sus clases van al punto. Y es muy flexible a la hora de realizar las calificaciones de las evaluaciones.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2023-06-15T00:00:00+00:00'::TIMESTAMPTZ, '692c06585972592e2015ae24e99f94ba91bf6295f4a753fbafe3ab5213b3cf5c'::TEXT, ARRAY[2962, 2965]::BIGINT[]),
    (693::BIGINT, 'Las clases con Leo son cortas, emplea el tiempo justo para que los temas queden claros. Responde rápido cuando uno tiene dudas. En sí él califica chill en los proyectos, el problema es con su asistente que el resto de trabajos sí califica duro.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2022-12-30T00:00:00+00:00'::TIMESTAMPTZ, 'b96b8fe4a283d813df9bd4cec145ce1c21f7e87ef92d8aeec3e58e70e1493e9f'::TEXT, ARRAY[2962]::BIGINT[]),
    (693::BIGINT, 'Las clases van al punto, explica las veces que sean necesarias para entender el tema. Ponerle bastante a los proyectos eso si. Buen profesor.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2022-11-20T00:00:00+00:00'::TIMESTAMPTZ, '68f9b9095a402be303a78369bc096a10a6944bdb7908c58f3adb7465c0c925b7'::TEXT, ARRAY[2962, 2965]::BIGINT[]),
    (693::BIGINT, 'Es bastante comprensivo si nota que usted le pone y se interesa por el curso. A pesar de ser un curso presencial de asistencia obligatoria no pasaba lista. El curso en sí es bastante complejo por lo que no basta con solo la explicación del profe pero siempre es bastante claro. Recomendado al 100%.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Respetado por los estudiantes', 'Brinda apoyo']::TEXT[], '2022-11-14T00:00:00+00:00'::TIMESTAMPTZ, 'fab19241103a8c9eb8670d92c969a94bdd90ebecae38f427142624bd3d121e0b'::TEXT, ARRAY[2965]::BIGINT[]),
    (693::BIGINT, 'Mu buen profe, siempre deja todo claro, simplemente recomendales que aprenden un poco de java antes, porque en si este curso es pura teoria'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2022-11-14T00:00:00+00:00'::TIMESTAMPTZ, '1fac8793740d1d579358deafb1860f1ab470cbbc73543581418c7a87cddf0e3b'::TEXT, ARRAY[2962, 2965]::BIGINT[]),
    (693::BIGINT, 'Es un buen profesor y deja claro lo que se debe de hacer en las evaluaciones, lo único que siento es que es apropiado que usted mismo investigue un poco de Python, pues se ve algo mas teórico que práctico, pero el profe por lo general le ayuda en caso de tener una duda al respecto de algo.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Pocos exámenes', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2022-06-27T00:00:00+00:00'::TIMESTAMPTZ, 'c51ad20d483732dfd987f29e7970ff4f7308713d7928b9a409a8a9988570d0b0'::TEXT, ARRAY[1249]::BIGINT[]),
    (693::BIGINT, 'Es buen profe muy simpático, las clases son cortas y las evaluaciones no son tan rudas, como consejo investigar un poco de python antes de llevar el curso.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2022-06-27T00:00:00+00:00'::TIMESTAMPTZ, '00731a0af88cee8e87a6b2ee50b806324c2bc5bb994a4fa8ec9cfda21691bf4c'::TEXT, ARRAY[2511, 2513]::BIGINT[]),
    (693::BIGINT, 'Sus clases son teoricas y muy cortas, si se no sabe mucho de Python es mejor buscar en otros lados sobre los temas del curso pero igualmente eso es algo propio del curso'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Tomaría su clase nuevamente']::TEXT[], '2022-06-18T00:00:00+00:00'::TIMESTAMPTZ, 'd485e67e6a6970e34a16aa0a4cccf690c0c4acf44b6e5b7d8809e7e2f8fcbeec'::TEXT, ARRAY[2511, 2513]::BIGINT[]),
    (693::BIGINT, 'El profesor ayuda bastante, las clases son cortas y únicamente se ve teoria , en clases no se programa por lo que es recomendable investigar de antemano sobre JAVA y aprender al menos lo básico, se debe ser súper autodidacta pero es cosa del curso no de los profes, quices fáciles y teoricos.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da crédito extra', 'Aspectos de calificación claros', 'Brinda apoyo']::TEXT[], '2022-01-01T00:00:00+00:00'::TIMESTAMPTZ, '69e58c459922494a17ac5f637a062228e9a8fa100fb753076c42e5e921b9b95f'::TEXT, ARRAY[2962, 2965]::BIGINT[]),
    (693::BIGINT, 'Muy buen profesor, es agradable y más bien hace la malla curricular mas lograble al reducir la cantidad de evaluaciones, ademas de hacer clases cortas y a veces asincrónicas, sólo que a veces confunde en sus explicaciones. También es muy flexible con las entregas de los trabajos.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Respetado por los estudiantes', 'Pocos exámenes']::TEXT[], '2021-12-06T00:00:00+00:00'::TIMESTAMPTZ, 'c45c83684ada6a65f9253fe8b72ec0cbf321b8ae53864458bda5f86fe83a8709'::TEXT, ARRAY[2962]::BIGINT[]),
    (693::BIGINT, 'El profe es muy conciso con las clases y explica de manera sencilla los conceptos, responde las consultas con bastante rapidez y es comprensivo con los estudiantes. Lo único malo es que no motiva la participación en clase lo cual en virtual complica saber con quien hacer los proyectos.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo']::TEXT[], '2021-11-27T00:00:00+00:00'::TIMESTAMPTZ, 'eefe508704858a7307129e57996977f899a54ba345d3d005e776d145f23eddcd'::TEXT, ARRAY[2962, 2965]::BIGINT[]),
    (693::BIGINT, 'Buen profe, explica muy bien y siempre te brinda ayuda'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2021-02-03T00:00:00+00:00'::TIMESTAMPTZ, '958fc3b3a88ffe15866cabeb382b90d3c6ffac842661741059540777bab20619'::TEXT, ARRAY[2962]::BIGINT[]),
    (693::BIGINT, 'Es un profe excelente, siempre está dispuesto a presentar su clase de la mejor manera y atiende cualquier duda. Las evaluaciones son un poco duras pero aprendes muchísimo. Super buena gente, recomendado.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Muchos proyectos grupales']::TEXT[], '2021-01-28T00:00:00+00:00'::TIMESTAMPTZ, '10117eeb7a54261d12c793d94fbf206a4149b37bd6277e104d036d33151fd995'::TEXT, ARRAY[2962]::BIGINT[]),
    (693::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2020-12-11T00:00:00+00:00'::TIMESTAMPTZ, 'fc14b16e58faa0e62d3f8ff501c4bade4f1eaed301ec00853ef6b878a0618538'::TEXT, ARRAY[2511, 2513]::BIGINT[]),
    (693::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2020-08-19T00:00:00+00:00'::TIMESTAMPTZ, '2b4e226ad85dc54d097f6945505063dc642fa32664b606a944b693b5a0b09640'::TEXT, ARRAY[2511, 2513]::BIGINT[]),
    (693::BIGINT, 'Muy recomendado, bastante facilidad para resolver dudas,es muy buena gente y a mi opinión explica bastante bien.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2020-08-17T00:00:00+00:00'::TIMESTAMPTZ, '83825d05583ef81f9aa766c0aa8cdde05709d091762fdc7a7f00c3ae5252ebb3'::TEXT, ARRAY[2511]::BIGINT[]),
    (693::BIGINT, 'Excelente profe, brinda mucha ayuda, siempre está dispuesto a aclarar dudas. Los proyectos son exigentes, evidentemente para aprender bastante, es muy tranquilo en el sentido de que no se estresa, ni es brusco. Recibiría clases con el sin duda'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2020-08-11T00:00:00+00:00'::TIMESTAMPTZ, '8cd2346e695d84b90b4a160f04ce09fdb0eda5866680f2d3a5dbed65bc95919b'::TEXT, ARRAY[2513]::BIGINT[]),
    (693::BIGINT, 'Explica bastante bien, es claro respecto a los temas, sus evaluaciones tienen una buena dificultad, ni muy fácil ni muy difícil, si uno le pregunta es probable que lo ayude. Las clases no son muy largas, pero sí son concisas y claras mientras le pongas atención.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2020-07-16T00:00:00+00:00'::TIMESTAMPTZ, '2a1f453cbb7055757f108bd20525ef3dfc6812af6ecf8df5ed175724b1846de2'::TEXT, ARRAY[2511]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
